"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5587"],{9609(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>l,frontMatter:()=>r,contentTitle:()=>o,toc:()=>d,assets:()=>c});var i=JSON.parse('{"id":"reference/admin/profileManagement","title":"Managing Profiles","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/admin/profileManagement.md","sourceDirName":"reference/admin","slug":"/reference/admin/profileManagement","permalink":"/personal-av-docs/docs/reference/admin/profileManagement","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/admin/profileManagement.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Managing Profiles","sidebar_label":"Managing Profiles","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/reference/admin/profileManagement","format":"md"}}'),a=t(4848),s=t(8453);let r={title:"Managing Profiles",sidebar_label:"Managing Profiles",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/reference/admin/profileManagement",format:"md"},o,c={},d=[];function h(e){let n={a:"a",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(n.p,{children:[":::note Edition\n",(0,a.jsx)(n.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(n.a,{href:"https://doc.airvantage.net/connectivity/reference/admin/profileManagement",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(n.p,{children:"Managing Profiles\nHow to add new user and manage user profile?\nHow to set up IMEI lock?\nFAQ\nReferences\nAccount Management\nOrders\nBilling\nAdministration\nSubaccounts\nConnectivity Management\nDashboard\nMonitor\nConfigure\nAPI, Connectors & Other Services\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nUSSD Gateway\nMore\nProduct page\nSearching...\nMatching results\nManaging Profiles\nProfiles control which entities and features are accessible/available to a given user. Profiles apply to users within an account and how partners access an account when partnerships are defined.\nPre-defined profiles are provided in the company, but an administrator can create additional profiles as required to define different access rights for their users. Profiles are listed in the\nAdministration\n>\nProfiles\nsection and can be reviewed and edited from the\nProfile Details\npage.\nNote:\nThis section of the user interface is generated dynamically and not all features and settings will be displayed for all users.\nFrom the\nProfiles\nsection you can:\nCreate a profile (\nonly administrators\ncan create new profiles)\nView\nprofile details\nEdit a profile\nDelete a profile\nProfile Details\nProfile details are divided into the following tabs which define access in AirVantage.\nAccount Network\nAccounts\nDevice\nEntities\nServer\nUser Interface\nAccount Network\nThe\nAccount Network\ntab defines which entities within the AirVantage account (e.g., company, labels, partners, users, etc.) can be administered.\nAPI Client\nAPI Clients provide API access to data in the Company. These settings determine what the user can do with APIs in the AirVantage account.\nCreate\n: Create new API clients.\nDelete\n: Delete API clients.\nEdit\n: Edit existing API clients.\nView\n: View existing API clients.\nCompany\nThe\nCompany\nrights enable users to see details about the Company.\nView Administrators\n: View details of the administrators of the account (\nSecurity\nsection).\nView Details\n: View the details of the company itself.\nLabels\nProvides the ability to manage with labels in the Company.\nCreate\n: Create new labels and edit existing labels.\nDelete\n: Delete labels.\nView\n: View existing labels.\nOperator\nOperator Account\nProvides the ability to manage Operator accounts, which are used for third-party subscription management.\nCreate\n: Create a new Operator account.\nEdit\n: Edit existing Operator accounts.\nView\n: View existing Operator accounts.\nView Restricted Parameters\n: View parameters which are set as\nrestricted\nin the original Operator account.\nPartners\nProvides the ability to manage the Partnerships with your Company. Partners are other companies which are connected to your Company account.\nRequest partnership\n: Enables the user to request partnerships with other Companies.\nView\n: View existing Partners.\nRequests\nALMS allows for Partners to register devices into a customer\u2019s ALMS Company. This feature requires that the customer accept the Partnership request.\nAccept/Reject\n: Gives the user the rights to manage Partnership requests.\nProfiles\nProvides the ability to manage user profiles.\nView\n: View existing profiles.\nSMS\nSMS Account\nSMS accounts can be used to send SMS\u2019s from AirVantage via an SMS gateway account. This profile enables the user to manage those SMS accounts.\nCreate\n: Create an SMS account.\nEdit\n: Edit existing SMS accounts.\nView\n: View existing SMS accounts.\nView Restricted Parameters\n: View parameters which are set as\nrestricted\nin the original SMS account.\nUsers\nProvides the ability to manage user accounts.\nRead\n: View existing users and their associated profiles.\nWrite\n: Access the\nInvite a User\nfeature (create new users) and the ability to remove (delete) users.\nAccounts\nThe\nAccounts\ntab defines account-related activities for the finance-oriented functions (ordering, invoicing) that can be performed in AirVantage.\nInvoicing\nIf your account type supports invoicing, these rights control access to the invoicing details.\nRead\n: View invoices which were generated on the platform.\nWrite\n: Update electronic payment methods and manage invoice recipients.\nOrdering\nIf your account supports ordering directly for AirVantage,\nOrdering\nrights control access to ordering information and who can order products.\nRead\n: View orders, delivery contacts, and product references.\nWrite\n: Place new orders and update order details and delivery contacts.\nRenewal\nIf your account includes pre-paid offers,\nRenewal\nrights control access to creating renewal quotes for devices due for renewal in the next 12 months.\nRead\n: View renewal quotations.\nWrite\n: Create new renewal quotations.\nSLA (Service Level Agreement)\nIf your account has an SLA with Sierra Wireless, these rights control access to the information about the SLA.\nRead\n: View the metrics of the SLA performance.\nSSO (Single Sign-On)\nSierra Wireless offers SSO capabilities which are activated at the account level. See\nHow to configure SSO for my account\nfor more information.\nWrite\n: Configure SSO for the account.\nDevice\nThe\nDevice\ntab defines whether or not a user can perform device-management operations.\nDevice Management\nActions\n: Defines whether a user can perform the following actions on their systems:\nreboot\nwakeup\nsynchronize\nconfigure heartbeat.\nThese features are managed through the\nAction\nbuttons on the\nMonitor\npage.\nSee\nCreate system management operations\nin the\nMonitor\ndocumentation for full details.\nEntities\nThe\nEntities\nsections define the operations which users can perform on entities. This section has the most commonly used system elements.\nAlerts\nAirVantage has powerful alerting capabilities. See\nAlerts\nin the in the\nMonitor\ndocumentation for full details.\nView\n: View alerts which have been triggered in AirVantage.\nAlert Rule\nThe\nAlert Rule\nrights determine whether users can interact with the\nAlert Rule creation\nfeatures in the\nConfigure\nsection of AirVantage. See\nHow to create a new alert rule\nfor more information.\nCreate/Edit/Delete\n: Create, edit, and/or delete alert rules.\nSubscribe\n: Manage webhooks (external URLs) when used with Alerts. When you create an Alert Rule, you can configure webhooks to be invoked when an alert is raised.\nView\n: View (but not edit) the alert rules.\nDevice Certificates\nThe\nDevice Certificates\nrights determine whether users can interact with the\nCertificates\nfeatures in the\nConfigure\nsection of AirVantage. See\nHow to manage certificates\nfor more information.\nRead\n: View device certificates and certificate-related alert rules.\nWrite\n: Regenerate or re-enroll certificates for multiple systems.\nBoth Read and Write access allow these users to view the Certificates page under Configure > Certificates.\nApplications\nFirmware for devices which are managed by AirVantage are referred to as\napplications\n. In addition, for some systems managed in AirVantage, users can publish applications which can then be deployed to the devices in the field. see\nHow to upgrade firmware on my ALEOS gateways\nfor more information.\nCreate\n: Create a new application in the company.\nDelete\n: Delete existing applications.\nEdit\n: Edit existing applications.\nPublish\n: Publish the selected application and make it available for use in your company. For example, this action is mandatory before you can perform a bulk installation.\nRelease\n: Upload a new application or a new revision of an existing application.\nView\n: View the state and properties of existing applications. You can also download the application package used at the time the application has been released in AirVantage.\nDatasets\nA\ndataset\nis a list of device parameters which a user would like retrieved from their gateways. It\u2019s used to collect data from the device that is not included in the\nDefault Status Report\n. see\nHow to retrieve device data in a dataset\nfor more information.\nCreate\n: Create a new dataset.\nDelete\n: Delete an existing dataset.\nView\n: View existing datasets.\nGroups\nGroups\nare collections of systems that share common attributes such as label, router model, firmware version, or any combination of these.\nRead\n: View groups and group details. To view the systems included in a group, the user needs the Systems View and Gateways View rights for that group. See\nSystems\nbelow.\nWrite\n: Modify the group attributes and add other users to the group. To modify the systems included in a group, the user needs the rights related to the operations the user needs to perform at the device group level: Systems View, Gateways View and Operations, for example.\nGateways\nA\nGateway\nis a component of a System in AirVantage. It represents the physical device and is generally linked to a model of AirLink router or gateway (e.g., AirLink XR80). It\u2019s important to give the same rights to Gateways, Subscriptions, and Systems so users have the complete range of rights needed to manage AirLink routers and gateways in ALMS.\nCreate\n: Create a new gateway, as part of a System.\nDelete\n: Delete the gateway from a System.\nEdit\n: Edit an existing gateway.\nView\n: View an existing gateway.\nTransfers\nAccept/Reject\n: Accept or reject requests to transfer a gateway, either between Systems or companies.\nCreate\n: Initiate the transfer of a gateway, either between Systems or between companies.\nOperations\nAll actions performed on entities within an AirVantage company generate\nOperations\n. This includes actions such as firmware updates, reboots, or applying a template.\nTrigger\n: Trigger operations to occur on AirVantage. Include this right for any user who needs to perform actions on Systems in the company.\nReports\nThis set of profiles are dedicated to ALMS users who have access to\nAdvanced Mobility Reporting\n(AMR). Any users who need to interact with reports in AMR must be provided with these privileges.\nRead\n: Open existing reports. Provide this right for users who only need to access reports, but do not need to create or edit reports.\nWrite\n: Open existing reports. Provide this right for users who need to create or edit reports. A new report cannot be created without this privilege.\nSettings (Templates)\nSettings are used to define Templates in the ALMS user interface and contain the configuration for a router or gateway.\nCreate\n: Create and edit a Template.\nDelete\n: Delete an existing Template.\nView\n: View an existing Template.\nSubscriptions\nA\nSubscription\nis a component of a System and contains the configuration of the connectivity defined with the cellular operator. Subscriptions may include Sierra Wireless or third-party cellular connectivity. It\u2019s important to give the same rights to Gateways, Subscriptions, and Systems for users to have the complete range of rights needed to manage AirLink routers and gateways in ALMS.\nCreate\n: Create a subscription for the System.\nDelete\n: Delete an existing subscription.\nEdit\n: Edit an existing subscription.\nView\n: View an existing subscription.\nIMEI lock\n: Lock/Unlock an existing subscription\nExport\n: Export an existing subscription\nOperations\nLaunch\n: Launch Subscription operations such as\nActivate\nor\nSuspend\n.\nUsages\nThe Usages right enables users to manage the importation of third-party operator data into their AirVantage account.\nCreate\n: Create a connection to a third-party operator account to allow for usage data to be brought to the AirVantage account.\nSystems\nA\nSystem\nis the primary entity in AirVantage and the core representation used to define and interact with a real device. A system is composed of:\nGateway\n: Physical device (router, gateway or module) enabling the connectivity of the System.\nSubscription\n: Configuration of the connectivity defined with the cellular operator. You can have one or more subscriptions.\nApplications\n: Define a piece of logic executing on the system. It can be the device\u2019s firmware or a separate software application running on the device.\nIt is important to give the same rights to Gateways, Subscriptions, and Systems for users to have the complete range of rights needed to manage AirLink routers and gateways in ALMS.\nActivate\n: Activate a new system. This is important for ALMS users who need to register and activate new routers and gateways and for Connectivity users that need to activate SIMs.\nCreate\n: Create a new System. This could be manual or automated through the registration process.\nDelete\n: Delete an existing System.\nEdit\n: Edit an existing system. This could include adding or removing subscriptions or gateways as components of the system.\nExport\n: Export data about the Systems.\nResume\n: Reactivate a system that was suspended.\nSuspend\n: Suspend Systems, preventing them from communicating with AirVantage. This feature may not be supported on your offer.\nTerminate\n: Terminate the system in the Company. As this feature can be harmful, it is recommended that most users are not provided this capability.\nView\n: View existing systems. Almost all AirVantage users should have this user right.\nChange\nThese rights enable users to change the offer and its options on a System. An offer represents the entity used to define features of the service and to bill the airtime consumption of the Systems. An offer can have some options which can be added or removed on Systems.\nOffer\n: Change the Offer assigned to the system. In some cases, Offers cannot be changed by the users of the account and the customer must contact Sierra Wireless Customer Support.\nOptions\n: Change options associated with the Offer. Not all Offers have options.\nNetwork\nFor Systems which include Sierra Wireless connectivity, these permissions enable the user to manage the state of the Subscription.\nDetach\n: Detach Systems from the network. This operation is only possible on systems linked to a\nSIERRA WIRELESS\nsubscription.\nStatus\n: Obtain the network status of a selection of Systems. This operation is only possible on systems linked to a\nSIERRA WIRELESS\nsubscription.\nSwap SIM\n: Swap SIMs between two Systems.\nData\nRetrieve Data\n: Trigger a command to retrieve data from the System.\nSend\nFor some classes of Systems, the user can trigger commands from AirVantage which are executed on the device.\nCommand\n: Send a command to a system. Commands must be defined in one of the applications running on your system. For some models of AirLink routers and gateways, they can accept AT commands.\nSend File\n: Send files to supported System types.\nSMS\n: Send a text SMS to one or multiple systems.\nSettings\nApply Settings\n: Access the\nApply Settings\nfeature. This feature enables the user to apply up to 15 settings to multiple systems. An example use for this feature is to update the login password on your devices and give each one a unique value. See\nHow to change settings on multiple devices\nfor more information\nTransfers\nThe\nTransfer\nright allow for the transfer of a selection of Systems to a Partner Company.\nCreate\n: Transfer Systems between the partnered accounts.\nZones\nZones\nare a feature of\nAdvanced Mobility Reporting\n(AMR). A Zone is a geographic area that enables the user to include or exclude areas for reporting (also referred to as \u201Cgeofencing\u201D). Any users who need to interact with reports in AMR must be provided with these privileges.\nCreate\n: Define a new Zone.\nDelete\n: Delete a Zone.\nView\n: View existing Zones.\nServer\nThe\nServer\ntab configures server events for pop-up notifications on the bottom-right of the screen for operations, report completion, and alerts.\nNotifications\nNotifications\n: Enable or disable notifications. This right should be given to all users.\nUser Interface\nActivities\nThe\nUser Interface\ntab defines which activities can be visible to the user in the primary AirVantage user interface. It determines which primary interface elements (\u201CActivities\u201D) are visible to the user.\nConfigure\n: Create System elements such as Alert Rules, Templates and Datasets. Access should be provided to any user who needs to create these system elements.\nDevelop\n: Manage applications and control access to API clients. This Activity is not needed by most users.\nInventory\n: Provides access to Systems which are in\nInventory\nor\nMaintenance\nmode. This Activity is disabled by default for ALMS users.\nMonitor\n: Primary Activity for managing Systems in AirVantage. All users need access to this Activity.\nRegister\n: Register devices into a user\u2019s Company. Any user who needs to register new Systems must be given access to this Activity.\nDashboards\nAirVantage provides sophisticated dashboarding capabilities. See\nDashboard\nfor more information.\nManage (Share & Transfer)\n: Create custom dashboards. This enables the user to share their dashboards within their Company and to transfer dashboards to partner organizations. This right must be given to any user who needs to create custom dashboard."})]})}function l(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>o});var i=t(6540);let a={},s=i.createContext(a);function r(e){let n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);